import{_ as t,o as a,c as i,a0 as o}from"./chunks/framework.DVUHX04-.js";const s="/pi-extensions/assets/context-cap.C8DusT8a.png",m=JSON.parse('{"title":"context-cap extension","description":"","frontmatter":{},"headers":[],"relativePath":"extensions/context-cap.md","filePath":"extensions/context-cap.md","lastUpdated":1789775493000}'),n={name:"extensions/context-cap.md"};function r(l,e,c,p,d,h){return a(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="context-cap-extension" tabindex="-1">context-cap extension <a class="header-anchor" href="#context-cap-extension" aria-label="Permalink to &quot;context-cap extension&quot;">​</a></h1><p>Caps the effective context window for a pi session, so auto-compaction fires early and prompts stay small:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --context-window</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 32000</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># or</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PI_CONTEXT_WINDOW</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">32000</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> pi</span></span></code></pre></div><p>The flag wins over the env var. The value is a token count, not a percentage.</p><h2 id="screenshot" tabindex="-1">Screenshot <a class="header-anchor" href="#screenshot" aria-label="Permalink to &quot;Screenshot&quot;">​</a></h2><p>Startup with <code>--context-window 100000</code>: the one-time notice, and the footer showing the capped window as the model&#39;s budget.</p><p><img src="`+s+'" alt="context-cap startup notice"></p><h2 id="behavior" tabindex="-1">Behavior <a class="header-anchor" href="#behavior" aria-label="Permalink to &quot;Behavior&quot;">​</a></h2><ul><li>The cap is a ceiling: the effective window is the smaller of the cap and the model&#39;s resolved window (after <code>models.json</code> <code>modelOverrides</code>). It never grows a window.</li><li>It is session-wide: the initial model, model switches, scoped-model cycling, and resume all operate under the cap. The <code>/model</code> picker and the footer context percentage show the capped window.</li><li>Compaction timing, overflow detection, and the footer percentage all use the capped window, because pi reads one field: <code>model.contextWindow</code>.</li><li>A one-time notice confirms the active cap at startup.</li></ul><h2 id="rejection" tabindex="-1">Rejection <a class="header-anchor" href="#rejection" aria-label="Permalink to &quot;Rejection&quot;">​</a></h2><p>pi reports an error and runs uncapped when:</p><ul><li>the value is not a positive integer, or</li><li>the cap is at or below <code>compaction.reserveTokens</code> (default 16384). A cap that small would compact every turn.</li></ul><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>On session start the extension re-registers each provider that has a model above the cap with capped copies of its full model list, and clamps the model objects the session already resolved in place. See <a href="/pi-extensions/adr/0004-context-window-cap-via-provider-reregistration.html">ADR 0004</a>.</p><h2 id="known-edges" tabindex="-1">Known edges <a class="header-anchor" href="#known-edges" aria-label="Permalink to &quot;Known edges&quot;">​</a></h2><ul><li>Providers whose model list pi refreshes from the network after startup (for example a local llama.cpp server) keep the capped list taken at session start until the next session.</li><li>A model with no configured auth is left untouched.</li></ul>',16)])])}const w=t(n,[["render",r]]);export{m as __pageData,w as default};
